window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-87e5582087a2fd60"]={"versions": [{"id": "FIG-87e5582087a2fd60", "releases": ["R1.3.0", "R17-03_R1.1.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm auf Protokollebene im Kontext des Remote Event Communication Protocol (RECP). Das Diagramm visualisiert das Nachrichtenformat und den Übertragungsweg für die Statusnachricht des Rückgabewerts von Diagnosemodus 4 (Mode4 Return Value Status Message) zwischen zwei Steuergeräten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Source Section ECU</strong>: Sendendes Steuergerät (Quellknoten), das den Status des Diagnosemodus $4 bereitstellt und versendet.\n</li><li><strong>Destination Section ECU</strong>: Empfangendes Steuergerät (Zielknoten), an das die Statusnachricht übermittelt wird.\n</li><li><strong>Mode $4 Return Value Status Message</strong>: Strukturierter Nachrichtenframe, aufgeteilt in:\n<ul class=\"fig-list\"><li>Header-Bereich (lila codiert):\n<ul class=\"fig-list\"><li><code>MSG_TYPE</code>: Nachrichtentyp-Identifikator (<code>TYP_MSTP</code>, Byte 0).\n</li><li><code>CLIENT_ID</code>: Kennung des anfordernden Clients (<code>TYP_CLID</code>, Byte 1).\n</li><li><code>RESERVED</code>: Reserviertes Feld (<code>STRCT_RESVD</code>, Bytes 2–4).\n</li></ul>\n</li><li>Nutzdaten-Bereich (blau codiert):\n<ul class=\"fig-list\"><li><code>MODE4_RET</code>: Eigentlicher Rückgabewert des Modus $4 (<code>TYP_MODE4_RET</code>, Byte 5).\n</li></ul>\n</li><li>Tail-Bereich (grün codiert):\n<ul class=\"fig-list\"><li><code>MSG_CTR</code>: Nachrichtenzähler zur Sequenz- und Übertragungsüberwachung (<code>TYP_MSGCTR</code>, Byte 6).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die <code>Source Section ECU</code> generiert die Statusnachricht für den Modus $4 und befüllt die Header-Felder (<code>MSG_TYPE</code>, <code>CLIENT_ID</code>, <code>RESERVED</code>), den Rückgabewert (<code>MODE4_RET</code>) sowie den zählerbasierten Nachrichtenabschluss (<code>MSG_CTR</code>).\n</li><li>Die assemblierte Nachricht wird serialisiert und über den Kommunikationspfad von der Quell-ECU zur Ziel-ECU übertragen.\n</li><li>Die <code>Destination Section ECU</code> empfängt die Nachricht, validiert Metadaten und Nachrichtenzähler und verarbeitet den enthaltenen Rückgabewert weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Frame-Struktur definiert ein festes Datenlayout über 7 Bytes (Byte 0 bis Byte 6).\n</li><li>Die Header-Felder dienen dem Routing und der Zuordnung der Antwort zum anfragenden Client.\n</li><li>Das Tail-Feld <code>MSG_CTR</code> muss für Integritätsprüfungen und Erkennung von Nachrichtenverlusten ausgewertet und fortlaufend inkrementiert werden.\n</li><li>Datenstrukturen und Typdefinitionen (insbesondere <code>TYP_MODE4_RET</code>) müssen kompatibel zu den Definitionen der Diagnostic Status Information (DSI) implementiert sein.\n</li></ul>"}, {"id": "FIG-a1b4952cef2085fe", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm auf Protokollebene im Kontext des Remote Event Communication Protocol (RECP). Das Diagramm visualisiert das Nachrichtenformat und den Übertragungsweg für die Statusnachricht des Rückgabewerts von Diagnosemodus 4 (Mode4 Return Value Status Message) zwischen zwei Steuergeräten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Source Section ECU</strong>: Sendendes Steuergerät (Quellknoten), das den Status des Diagnosemodus $4 bereitstellt und versendet.\n</li><li><strong>Destination Section ECU</strong>: Empfangendes Steuergerät (Zielknoten), an das die Statusnachricht übermittelt wird.\n</li><li><strong>Mode $4 Return Value Status Message</strong>: Strukturierter Nachrichtenframe, aufgeteilt in:\n<ul class=\"fig-list\"><li>Header-Bereich (lila codiert):\n<ul class=\"fig-list\"><li><code>MSG_TYPE</code>: Nachrichtentyp-Identifikator (<code>TYP_MSTP</code>, Byte 0).\n</li><li><code>CLIENT_ID</code>: Kennung des anfordernden Clients (<code>TYP_CLID</code>, Byte 1).\n</li><li><code>RESERVED</code>: Reserviertes Feld (<code>STRCT_RESVD</code>, Bytes 2–4).\n</li></ul>\n</li><li>Nutzdaten-Bereich (blau codiert):\n<ul class=\"fig-list\"><li><code>MODE4_RET</code>: Eigentlicher Rückgabewert des Modus $4 (<code>TYP_MODE4_RET</code>, Byte 5).\n</li></ul>\n</li><li>Tail-Bereich (grün codiert):\n<ul class=\"fig-list\"><li><code>MSG_CTR</code>: Nachrichtenzähler zur Sequenz- und Übertragungsüberwachung (<code>TYP_MSGCTR</code>, Byte 6).\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die <code>Source Section ECU</code> generiert die Statusnachricht für den Modus $4 und befüllt die Header-Felder (<code>MSG_TYPE</code>, <code>CLIENT_ID</code>, <code>RESERVED</code>), den Rückgabewert (<code>MODE4_RET</code>) sowie den zählerbasierten Nachrichtenabschluss (<code>MSG_CTR</code>).\n</li><li>Die assemblierte Nachricht wird serialisiert und über den Kommunikationspfad von der Quell-ECU zur Ziel-ECU übertragen.\n</li><li>Die <code>Destination Section ECU</code> empfängt die Nachricht, validiert Metadaten und Nachrichtenzähler und verarbeitet den enthaltenen Rückgabewert weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Frame-Struktur definiert ein festes Datenlayout über 7 Bytes (Byte 0 bis Byte 6).\n</li><li>Die Header-Felder dienen dem Routing und der Zuordnung der Antwort zum anfragenden Client.\n</li><li>Das Tail-Feld <code>MSG_CTR</code> muss für Integritätsprüfungen und Erkennung von Nachrichtenverlusten ausgewertet und fortlaufend inkrementiert werden.\n</li><li>Datenstrukturen und Typdefinitionen (insbesondere <code>TYP_MODE4_RET</code>) müssen kompatibel zu den Definitionen der Diagnostic Status Information (DSI) implementiert sein.\n</li></ul>"}], "trans": [{"from": "FIG-87e5582087a2fd60", "to": "FIG-a1b4952cef2085fe", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a1b4952cef2085fe", "to": "FIG-87e5582087a2fd60", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
